from pathlib import Path
import subprocess,hashlib,json,datetime,stat
root=Path('/scratch/alpine/paco0228/ACE/results/ace_llm_intervention_staged_runtime_20261107_01')
results={}
for k,c in {'accounting':['sacct','-j','35343957','-n','-P','--format=JobIDRaw,JobID,JobName%60,State,ExitCode,AllocCPUS,ElapsedRaw,Account,AllocTRES%180,MaxRSS,TotalCPU'],'queue':['squeue','-u','paco0228','-h','-o','%i|%j|%T|%R|%a'],'job':['scontrol','show','job','-o','35343957']}.items():
 p=subprocess.run(c,capture_output=True,text=True,timeout=20);results[k]={'command':c,'returncode':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
rows=[line.split('|') for line in results['accounting']['stdout'].splitlines() if line.startswith('35343957'+'|')]
if len(rows)!=1 or rows[0][3] not in ('COMPLETED','FAILED','CANCELLED','TIMEOUT','OUT_OF_MEMORY','NODE_FAIL'):
 raise RuntimeError('job not conclusively terminal, never restart on observation failure')
files={}
manifest=root/'qualification/packed/manifest.json'
m=json.loads(manifest.read_bytes()) if manifest.exists() else None
for p in sorted(root.rglob('*')):
 if p.is_symlink():raise ValueError('unexpected output symlink')
 if not p.is_file():continue
 name=str(p.relative_to(root));n=p.stat().st_size
 if name=='qualification/packed/runtime.tar':
  files[name]={'bytes':n,'sha256':m['archive_sha256'] if m else None,'pin_origin':'supervised pack manifest' if m else 'incomplete archive, no independent remote byte pin'}
  if m and n!=m['archive_bytes']:raise ValueError('archive metadata changed')
 else:
  if n>64*1024*1024:raise ValueError('unexpected large nonarchive artifact')
  files[name]={'bytes':n,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'pin_origin':'fresh remote byte hash'}
print(json.dumps({'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'files':files,'results':results,'parent_accounting':rows[0]}))
